open('test/pedidos.test.js','a').write("""
const rastreioFalso = (fn) => ({ rastrear: fn })
const novoPedido = (app) => app.handle('POST', '/pedidos', { itens: [{ produtoId: 'p-100' }], cep: '01310100' })

test('GET /pedidos/{id}/rastreio devolve os eventos da TransNorte com o id como código', async () => {
  const chamadas = []
  const resposta = { codigo: 'ped-1001', eventos: [{ quando: '2026-03-02T09:00:00Z', descricao: 'Objeto postado', cidade: 'São Paulo' }] }
  const rastreio = rastreioFalso(async (codigo) => { chamadas.push(codigo); return resposta })
  const app = criarApp({ frete: freteFixo(), rastreio, agora: agoraFixo })
  const p = await novoPedido(app)
  const r = await app.handle('GET', `/pedidos/${p.body.id}/rastreio`)
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, resposta)
  assert.deepEqual(chamadas, [p.body.id])
})

test('GET /pedidos/{id}/rastreio devolve 404 PEDIDO_NAO_ENCONTRADO sem consultar a TransNorte', async () => {
  let chamou = false
  const rastreio = rastreioFalso(async () => { chamou = true })
  const r = await criarApp({ frete: freteFixo(), rastreio }).handle('GET', '/pedidos/ped-1/rastreio')
  assert.equal(r.status, 404)
  assert.equal(r.body.erro.codigo, 'PEDIDO_NAO_ENCONTRADO')
  assert.equal(chamou, false)
})

test('GET /pedidos/{id}/rastreio devolve 404 RASTREIO_NAO_ENCONTRADO quando a TransNorte não conhece o código', async () => {
  const app = criarApp({ frete: freteFixo(), rastreio: rastreioFalso(async () => null), agora: agoraFixo })
  const p = await novoPedido(app)
  const r = await app.handle('GET', `/pedidos/${p.body.id}/rastreio`)
  assert.equal(r.status, 404)
  assert.equal(r.body.erro.codigo, 'RASTREIO_NAO_ENCONTRADO')
})

test('GET /pedidos/{id}/rastreio devolve 503 RASTREIO_INDISPONIVEL quando a TransNorte falha', async () => {
  const app = criarApp({ frete: freteFixo(), rastreio: rastreioFalso(async () => { throw new Error('TransNorte respondeu 500') }), agora: agoraFixo })
  const p = await novoPedido(app)
  const r = await app.handle('GET', `/pedidos/${p.body.id}/rastreio`)
  assert.equal(r.status, 503)
  assert.equal(r.body.erro.codigo, 'RASTREIO_INDISPONIVEL')
})
""")
open('test/frete.test.js','a').write("""
test('TransNorte rastreia pelo código e devolve a resposta dela', async () => {
  const resposta = { codigo: 'ped-1001', eventos: [{ quando: '2026-03-02T09:00:00Z', descricao: 'Objeto postado', cidade: 'São Paulo' }] }
  const fetch = fetchFalso(resposta)
  const r = await criarTransNorte({ fetch, apiKey: 'k' }).rastrear('ped-1001')
  assert.deepEqual(r, resposta)
  assert.match(fetch.chamadas[0].url, /\\/rastreamentos\\/ped-1001$/)
  assert.equal(fetch.chamadas[0].init.headers['x-api-key'], 'k')
})

test('TransNorte rastrear devolve null no 404 e falha nos demais erros', async () => {
  assert.equal(await criarTransNorte({ fetch: fetchFalso({}, { status: 404 }) }).rastrear('x'), null)
  await assert.rejects(criarTransNorte({ fetch: fetchFalso({}, { status: 500 }) }).rastrear('x'), /TransNorte respondeu 500/)
})
""")

